//! Deterministic execution plans for ephemeral resource and integration environments.
//!
//! Plans contain only logical aliases and policy. Runtime ports and credentials
//! are generated by an `EnvironmentManager` and must never be serialized here.

use crate::v2::{IntegrationKindV2, IrV2, ResourceKindV2, ResourcePermissionV2};
use crate::{compile_v2, ir_v2_digest, CompileV2Error};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;

pub const ENVIRONMENT_PLAN_VERSION: u32 = 1;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ResourceServicePlanV1 {
    pub resource_id: String,
    pub kind: ResourceKindV2,
    pub version: String,
    pub private_alias: String,
    pub image_key: String,
    pub consumers: BTreeMap<String, Vec<ResourcePermissionV2>>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct IntegrationEmulatorPlanV1 {
    pub integration_id: String,
    pub kind: IntegrationKindV2,
    pub private_alias: String,
    pub operations: Vec<String>,
    pub consumers: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MigrationPlanV1 {
    pub resource_id: String,
    pub owner_node: String,
    pub migration_path: String,
    pub require_repeatable: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct EnvironmentPlanV1 {
    pub environment_plan_version: u32,
    pub ir_digest: String,
    pub plan_digest: String,
    pub network_egress: String,
    pub resources: Vec<ResourceServicePlanV1>,
    pub integrations: Vec<IntegrationEmulatorPlanV1>,
    pub migrations: Vec<MigrationPlanV1>,
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

pub fn plan_test_environment(ir: &IrV2) -> Result<EnvironmentPlanV1, Vec<CompileV2Error>> {
    compile_v2(ir)?;
    let mut resources = ir
        .resources
        .iter()
        .map(|resource| {
            let mut consumers = BTreeMap::new();
            for binding in ir
                .resource_bindings
                .iter()
                .filter(|binding| binding.resource == resource.id)
            {
                let mut permissions = binding.permissions.clone();
                permissions.sort();
                consumers.insert(binding.node.clone(), permissions);
            }
            ResourceServicePlanV1 {
                resource_id: resource.id.clone(),
                kind: resource.kind.clone(),
                version: resource.version.clone(),
                private_alias: resource.id.clone(),
                image_key: format!("{:?}", resource.kind).to_ascii_lowercase(),
                consumers,
            }
        })
        .collect::<Vec<_>>();
    resources.sort_by(|left, right| left.resource_id.cmp(&right.resource_id));

    let mut integrations = ir
        .integrations
        .iter()
        .map(|integration| {
            let mut operations = integration.operations.clone();
            operations.sort();
            let mut consumers = ir
                .integration_bindings
                .iter()
                .filter(|binding| binding.integration == integration.id)
                .map(|binding| binding.node.clone())
                .collect::<Vec<_>>();
            consumers.sort();
            consumers.dedup();
            IntegrationEmulatorPlanV1 {
                integration_id: integration.id.clone(),
                kind: integration.kind.clone(),
                private_alias: integration.id.clone(),
                operations,
                consumers,
            }
        })
        .collect::<Vec<_>>();
    integrations.sort_by(|left, right| left.integration_id.cmp(&right.integration_id));

    let mut migrations = ir
        .resources
        .iter()
        .filter_map(
            |resource| match (&resource.migration_owner, &resource.migration_path) {
                (Some(owner), Some(path)) => Some(MigrationPlanV1 {
                    resource_id: resource.id.clone(),
                    owner_node: owner.clone(),
                    migration_path: path.clone(),
                    require_repeatable: resource.require_repeatable_migrations,
                }),
                _ => None,
            },
        )
        .collect::<Vec<_>>();
    migrations.sort_by(|left, right| left.resource_id.cmp(&right.resource_id));

    let ir_digest = ir_v2_digest(ir);
    let digest_input = serde_json::to_vec(&(
        ENVIRONMENT_PLAN_VERSION,
        &ir_digest,
        &resources,
        &integrations,
        &migrations,
    ))
    .expect("environment plan serialization is infallible");
    Ok(EnvironmentPlanV1 {
        environment_plan_version: ENVIRONMENT_PLAN_VERSION,
        ir_digest,
        plan_digest: sha256(&digest_input),
        network_egress: "none".to_owned(),
        resources,
        integrations,
        migrations,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn service_stack_plan_is_private_and_deterministic() {
        let ir: IrV2 = serde_json::from_str(include_str!(
            "../../../../ir/examples/service-stack.ir-v2.json"
        ))
        .unwrap();
        let left = plan_test_environment(&ir).unwrap();
        let right = plan_test_environment(&ir).unwrap();
        assert_eq!(left, right);
        assert_eq!(left.network_egress, "none");
        assert_eq!(left.resources[0].private_alias, "primary-db");
        assert_eq!(left.integrations[0].private_alias, "payments");
        assert_eq!(left.migrations[0].owner_node, "api");
        let serialized = serde_json::to_string(&left).unwrap();
        assert!(!serialized.contains("password"));
        assert!(!serialized.contains("localhost"));
    }
}
